class Solution {
public:
    int numRookCaptures(vector<vector<char>>& board) {
        int rx = 0, ry = 0;
        for (int i = 0; i < 8; ++i) {
            for (int j = 0; j < 8; ++j) {
                if (board[i][j] == 'R') {
                    rx = i;
                    ry = j;
                }
            }
        }
        int dx[4] = {-1, 1, 0, 0};
        int dy[4] = {0, 0, -1, 1};
        int ans = 0;
        for (int d = 0; d < 4; ++d) {
            int x = rx + dx[d];
            int y = ry + dy[d];
            while (x >= 0 && x < 8 && y >= 0 && y < 8) {
                if (board[x][y] != '.') {
                    if (board[x][y] == 'p') ++ans;
                    break;
                }
                x += dx[d];
                y += dy[d];
            }
        }
        return ans;
    }
};
